def solve_m3():
    count = 0
    # Constraints: 0 <= b_i <= 6 for i=0, 1, 2, 3. b_3 >= 1.
    # Since max(b0 + 4*b1 + 7*b2) = 6 + 4*6 + 7*6 = 72.
    # We need 14*b3 <= 72, so b3 <= 5.

    for b3 in range(1, 6):
        for b2 in range(7):
            for b1 in range(7):
                # Calculate required b0
                # b0 = 14*b3 - 4*b1 - 7*b2
                required_b0 = 14 * b3 - 4 * b1 - 7 * b2

                # Check constraints on b0
                if 0 <= required_b0 <= 6:
                    count += 1
    return count

